package org.brightstats.stats;

import java.util.*;
import java.nio.file.*;
import com.google.gson.*;

public final class TetradChecks {
    private static int checks;
    private static void check(boolean value){checks++;if(!value)throw new AssertionError("Tetrad check "+checks);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid tetrad analysis accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        var gson=new GsonBuilder().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonArray cases=new JsonArray();for(int p=4;p<=25;p++){check(TetradAnalysis.tetrads(p,TetradAnalysis.Selection.CANONICAL_BASIS).size()==p*(p-3)/2);check(TetradAnalysis.tetrads(p,TetradAnalysis.Selection.REFERENCE_SUBSET).size()==(p==14?78:p*(p-3)/2));}Random random=new Random(20261115);double[][] data=new double[110][6];for(double[] row:data){double factor=random.nextGaussian();for(int j=0;j<row.length;j++)row[j]=j+(.5+.12*j)*factor+.5*random.nextGaussian();}var names=List.of("A","B","C","D","E","F");
        for(int p:new int[]{4,5,6})for(var selection:TetradAnalysis.Selection.values())for(var convention:RegressionBootstrap.Convention.values()){
            double[][] observations=Matrices.copy(data);if(p==6)for(double[] row:observations)row[3]+=.7*row[2];var blocks=List.of(new PlsSem.Block("Factor",java.util.stream.IntStream.range(0,p).toArray(),PlsSem.Mode.A),new PlsSem.Block("Short",new int[]{0,1,2},PlsSem.Mode.A));var options=new TetradAnalysis.Options(60,295948,.05,convention,true,selection,true);var fit=TetradAnalysis.fit(observations,names,blocks,options,null);check(fit.successful()==60&&fit.failed()==0&&fit.blocks().size()==1&&fit.skipped().size()==1);var terms=fit.blocks().get(0).terms();for(var term:terms){check(term.distribution().length==60);check(Arrays.stream(term.histogram().counts()).sum()==60);check(term.intervalAvailable());check(term.pValue()>=0&&term.pValue()<=1);check(term.bonferroniP()>=term.pValue());check(term.adjustedLower()<=term.lower()&&term.adjustedUpper()>=term.upper());}if(selection==TetradAnalysis.Selection.ALL_TETRADS){for(int sample=0;sample<60;sample++)check(Math.abs(terms.get(0).distribution()[sample]-terms.get(1).distribution()[sample]+terms.get(2).distribution()[sample])<1e-12);}
            JsonObject test=new JsonObject();test.add("observations",gson.toJsonTree(observations));test.add("names",gson.toJsonTree(names));test.add("blocks",gson.toJsonTree(blocks));test.add("options",gson.toJsonTree(options));test.add("result",gson.toJsonTree(fit));cases.add(test);
        }
        double[][] large=new double[80][14];List<String> largeNames=new ArrayList<>();for(int j=0;j<14;j++)largeNames.add("V"+j);for(double[] row:large){double factor=random.nextGaussian();for(int j=0;j<14;j++)row[j]=factor+.7*random.nextGaussian();}var block14=List.of(new PlsSem.Block("Large",java.util.stream.IntStream.range(0,14).toArray(),PlsSem.Mode.A));var reference=new TetradAnalysis.Options(40,295948,.05,RegressionBootstrap.Convention.REFERENCE_4_1_2_1,false,TetradAnalysis.Selection.REFERENCE_SUBSET,false);var result14=TetradAnalysis.fit(large,largeNames,block14,reference,null);check(result14.blocks().get(0).terms().size()==78);check(result14.blocks().get(0).warnings().stream().anyMatch(message->message.contains("rank is 77")));JsonObject test14=new JsonObject();test14.add("observations",gson.toJsonTree(large));test14.add("names",gson.toJsonTree(largeNames));test14.add("blocks",gson.toJsonTree(block14));test14.add("options",gson.toJsonTree(reference));test14.add("result",gson.toJsonTree(result14));cases.add(test14);
        for(var convention:RegressionBootstrap.Convention.values()){double[][] perfect=new double[8][4];for(int i=0;i<8;i++)Arrays.fill(perfect[i],i);var perfectBlocks=List.of(new PlsSem.Block("Perfect",new int[]{0,1,2,3},PlsSem.Mode.A));var settings=new TetradAnalysis.Options(40,42,.05,convention,true,TetradAnalysis.Selection.CANONICAL_BASIS,true);var fit=TetradAnalysis.fit(perfect,List.of("A","B","C","D"),perfectBlocks,settings,null);for(var term:fit.blocks().get(0).terms()){check(term.original()==0&&term.standardDeviation()==0);check(term.intervalAvailable()==(convention==RegressionBootstrap.Convention.REFERENCE_4_1_2_1));check(term.referenceSmallError()==(convention==RegressionBootstrap.Convention.REFERENCE_4_1_2_1));}JsonObject test=new JsonObject();test.add("observations",gson.toJsonTree(perfect));test.add("names",gson.toJsonTree(List.of("A","B","C","D")));test.add("blocks",gson.toJsonTree(perfectBlocks));test.add("options",gson.toJsonTree(settings));test.add("result",gson.toJsonTree(fit));cases.add(test);}
        var blocks=List.of(new PlsSem.Block("Factor",new int[]{0,1,2,3},PlsSem.Mode.A));reject(()->TetradAnalysis.fit(data,names,List.of(new PlsSem.Block("Short",new int[]{0,1,2},PlsSem.Mode.A)),TetradAnalysis.Options.defaults(),null));reject(()->new TetradAnalysis.Options(29,42,.05,RegressionBootstrap.Convention.STANDARD,true,TetradAnalysis.Selection.CANONICAL_BASIS,false));reject(()->new TetradAnalysis.Options(40,42,.05,RegressionBootstrap.Convention.STANDARD,false,TetradAnalysis.Selection.CANONICAL_BASIS,false));double[][] constant=Matrices.copy(data);for(double[] row:constant)row[0]=1;reject(()->TetradAnalysis.fit(constant,names,blocks,TetradAnalysis.Options.defaults(),null));reject(()->TetradAnalysis.tetrads(26,TetradAnalysis.Selection.REFERENCE_SUBSET));Thread.currentThread().interrupt();try{TetradAnalysis.fit(data,names,blocks,TetradAnalysis.Options.defaults(),null);throw new AssertionError("Tetrads ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"tetrad_cases\":"+cases.size()+",\"checks\":"+checks+"}");
    }
}
